            case 16:
                
                var numericInner = reader.ReadString()!;

                return new UniScalarValueNumeric { Inner = numericInner };
                
            
            case 17:
                
                var dateInner = reader.ReadString()!;

                return new UniScalarValueDate { Inner = dateInner };
                
            
            case 18:
                
                var timeInner = reader.ReadString()!;

                return new UniScalarValueTime { Inner = timeInner };
                
            
            case 19:
                
                var timestampInner = reader.ReadString()!;

                return new UniScalarValueTimestamp { Inner = timestampInner };
                
            
            case 20:
                
                var timestamp_tzInner = reader.ReadString()!;

                return new UniScalarValueTimestampTz { Inner = timestamp_tzInner };
                
            
            case 21:
                
                // The payload-less placeholder is skipped, not inspected.
                reader.Skip();
                return new UniScalarValueNull();
                
            
            default:
                throw new global::System.InvalidOperationException($"Unknown tag: {tag}");
        }
    }
}

